            fx.time.advanceBy(2_000)
            fx.coordinator.clear()
            val eventsBefore = fx.events.size

            fx.time.advanceBy(30_000)
            assertEquals("no timer event after clear()", eventsBefore, fx.events.size)
            fx.request(token)
