    }

    @Test
    fun clearDuringAFailureWindowDropsTheRestartedTimerToo() {
        for (type in types) {
            val fx = Fixture()
            val token = fx.begin(type, "p1", "x1")!!
            fx.script += { ClinicalCommandOutcome.Rejected(ClinicalCommandFailure.RECORD_CONFLICT) }
            fx.request(token)
