        }
    }

    @Test
    fun failedOrAmbiguousDeleteDispatchesDeleteFailedAndOffersNothing() {
        for (type in types) {
            for (outcome in listOf(
                ClinicalCommandOutcome.Rejected(ClinicalCommandFailure.STALE_REVISION),
                ClinicalCommandOutcome.Ambiguous,
