    @Test
    fun deleteOfARecordThatIsNotThereExecutesNothing() {
        for (type in types) {
            val fx = Fixture()
            fx.begin(type, "p1", "missing")
            fx.begin(type, "p3", "x1")
            // p2 has no "y1" in either section; p1's "onlyMed" is a medication only.
