    @Test
    fun newerOfferReplacesAndFinalisesTheOlder() {
        for (type in types) {
            val fx = Fixture()
            val first = fx.begin(type, "p1", "x1")!!
            fx.time.advanceBy(3_000)
            val second = fx.begin(type, "p1", "y1")!!
            assertNotEquals(type.name, first, second)
