        }
    }

    @Test
    fun newerOfferIsTheOnlyOneRestoredAndNeverTheOlderRecord() {
        for (type in types) {
            val fx = Fixture()
            val first = fx.begin(type, "p1", "x1")!!
            val second = fx.begin(type, "p1", "y1")!!
            fx.request(first)
