    @Test
    fun saveUndoDeletesExactlyTheSavedRecordAndExpiresAfter8000ms() {
        for (type in types) {
            val a = target(type)
            val saved = original(a)!!
            val receipt = ClinicalCommandReceipt(
                operationUuid = "op", patientId = "p1", recordKind = "X", recordId = "x1",
